using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}, kind = {personInfo.Kind}");

// Prove it works end-to-end: serialize using the typed info
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false if not available
//    Here we use a source-gen context that only knows about Person, not about int[].
var restricted = new PersonOnlyContext(new JsonSerializerOptions());

bool found = restricted.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person)  => found={found}, info={info?.Type.Name}");

bool foundArr = restricted.TryGetTypeInfo(typeof(int[]), out JsonTypeInfo? arrInfo);
Console.WriteLine($"TryGetTypeInfo(int[])  => found={foundArr}, info={arrInfo?.Type.Name ?? "(null)"}");

// ---
record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
partial class PersonOnlyContext : JsonSerializerContext;

